def transform(g):
    H,W=len(g),len(g[0]); fc=g[0][0]
    sep=next(c for c in range(W) if all(g[r][c]==0 for r in range(H)))
    frame_rows=[r for r in range(H) if all(g[r][c]==fc for c in range(sep))]
    blocks=[];r=0
    while r<H:
        if r in frame_rows: r+=1;continue
        r2=r
        while r2<H and r2 not in frame_rows: r2+=1
        blocks.append((r,r2));r=r2
    def pat(cells):
        rs=[r for r,c in cells];cs=[c for r,c in cells]
        r0,c0=min(rs),min(cs)
        return frozenset((r-r0,c-c0) for r,c in cells)
    holes=[]
    for a,b in blocks:
        cells=[(rr,c) for rr in range(a,b) for c in range(sep) if g[rr][c]==0]
        holes.append({'rows':(a,b),'pat':pat(cells)})
    seen=[[False]*W for _ in range(H)];shapes=[]
    for rr in range(H):
        for c in range(sep+1,W):
            if g[rr][c] and not seen[rr][c]:
                col=g[rr][c];stack=[(rr,c)];seen[rr][c]=True;cells=[]
                while stack:
                    y,x=stack.pop();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and sep<nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True;stack.append((ny,nx))
                shapes.append({'col':col,'pat':pat(cells)})
    assign={}
    for h in holes:
        m=[s for s in shapes if s['pat']==h['pat']]
        assign[h['rows']]=m[0]['col']
    out=[]
    for rr in range(H):
        blk=next((k for k in assign if k[0]<=rr<k[1]),None)
        out.append([fc if g[rr][c]!=0 else (assign[blk] if blk else 0) for c in range(sep)])
    return out
